// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"¡Bienvenidos a Español 2! Let's review the present tense, especially the verbs that break the rules.","blocks":[{"t":"key","text":"Stem-changing verbs change in all forms except nosotros and vosotros (the \"boot\"): e→ie (pensar: pienso), o→ue (dormir: duermo), e→i (servir: sirvo)."},{"t":"p","text":"\"Yo-go\" verbs are irregular only in the yo form: tengo, hago, pongo, salgo, digo, vengo, traigo."},{"t":"p","text":"Fully irregular verbs to know: ser (soy, eres, es…), ir (voy, vas, va, vamos, vais, van), estar, tener."},{"t":"p","text":"Ir + a + infinitive expresses the near future: Voy a estudiar (I'm going to study)."},{"t":"ex","problem":"Conjugate \"poder\" for \"they\"","steps":["o→ue in the boot: pued-"],"answer":"pueden"}]},{"say":"Reflexive verbs describe actions you do to yourself, like waking up and brushing your teeth.","blocks":[{"t":"key","text":"Reflexive verbs use reflexive pronouns that match the subject: me, te, se, nos, os, se. Levantarse: me levanto, te levantas, se levanta, nos levantamos, os levantáis, se levantan."},{"t":"p","text":"Common routine verbs: despertarse (to wake up), levantarse (to get up), ducharse (to shower), cepillarse los dientes (to brush one's teeth), vestirse (to get dressed), acostarse (to go to bed)."},{"t":"p","text":"The pronoun goes before a conjugated verb (Me ducho) or attaches to an infinitive (Voy a ducharme)."},{"t":"ex","problem":"Say \"I wake up at 6 and then I shower.\"","steps":["Despertarse (e→ie): me despierto"],"answer":"Me despierto a las seis y luego me ducho."}]}],[{"say":"The preterite tense talks about completed actions in the past. Ayer (yesterday) is a great clue word!","blocks":[{"t":"key","text":"Regular preterite endings:"},{"t":"list","items":["-ar (hablar): hablé, hablaste, habló, hablamos, hablasteis, hablaron.","-er/-ir (comer, vivir): comí, comiste, comió, comimos, comisteis, comieron."]},{"t":"p","text":"Spelling changes in the yo form: -car → -qué (busqué), -gar → -gué (llegué), -zar → -cé (empecé)."},{"t":"p","text":"Clue words: ayer, anoche (last night), la semana pasada (last week), el año pasado (last year)."},{"t":"ex","problem":"Say \"Last night I studied and ate dinner.\"","steps":["estudiar → estudié; cenar → cené"],"answer":"Anoche estudié y cené."}]},{"say":"Some of the most common verbs are irregular in the preterite. Memorize them and your storytelling will flow.","blocks":[{"t":"key","text":"Ser and ir share the same preterite forms: fui, fuiste, fue, fuimos, fuisteis, fueron. Context tells which: Fui al cine (I went) vs. Fue divertido (It was fun)."},{"t":"p","text":"Irregular stems with special endings (-e, -iste, -o, -imos, -isteis, -ieron), with no accents:"},{"t":"list","items":["tener → tuv-: tuve; estar → estuv-: estuve; poder → pud-: pude; poner → pus-: puse; hacer → hic-: hice (hizo); querer → quis-: quise; venir → vin-: vine.","decir → dij-: dije (dijeron); traer → traj-: traje."]},{"t":"p","text":"Stem-changing -ir verbs change in the third person: dormir → durmió, durmieron; pedir → pidió, pidieron."}]}],[{"say":"The imperfect describes how things used to be: habits, descriptions and ongoing actions in the past.","blocks":[{"t":"key","text":"Imperfect endings:"},{"t":"list","items":["-ar: hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban.","-er/-ir: comía, comías, comía, comíamos, comíais, comían."]},{"t":"p","text":"Only three irregular verbs: ser (era), ir (iba), ver (veía)."},{"t":"p","text":"Uses: repeated or habitual actions (Cuando era niño, jugaba al fútbol), descriptions (La casa era grande), time and age (Eran las tres; Tenía diez años), and ongoing actions in progress."},{"t":"p","text":"Clue words: siempre, todos los días, a menudo (often), de niño (as a child)."}]},{"say":"Choosing between the preterite and imperfect is the key to telling stories in Spanish.","blocks":[{"t":"key","text":"Preterite: completed actions at a specific time, a sequence of events, or something that interrupts. Imperfect: background, description, habits, and ongoing actions."},{"t":"p","text":"A common pattern: an ongoing action (imperfect) is interrupted by another action (preterite): Yo leía cuando sonó el teléfono (I was reading when the phone rang)."},{"t":"p","text":"Think of a movie: the imperfect sets the scene (it was raining, people were walking); the preterite moves the plot (suddenly, a car crashed)."},{"t":"ex","problem":"Choose: \"Hacía sol cuando nosotros ___ (salir).\"","steps":["The sunny weather is background (imperfect)","Leaving is a completed action that happened (preterite)"],"answer":"salimos"}]}],[{"say":"Commands tell people what to do. They're used in recipes, directions and everyday life.","blocks":[{"t":"key","text":"Affirmative tú commands use the él/ella present form: habla, come, escribe. Irregular tú commands: di, haz, ve, pon, sal, sé, ten, ven."},{"t":"p","text":"Negative tú commands use no + the subjunctive form: no hables, no comas, no escribas (switch the vowel: -ar verbs use -es, -er/-ir verbs use -as)."},{"t":"p","text":"Formal (usted) commands also use the subjunctive: hable, coma, escriba."},{"t":"p","text":"Pronouns attach to affirmative commands (Dímelo) but go before negative ones (No me lo digas)."},{"t":"ex","problem":"Tell a friend \"Do your homework, but don't watch TV.\"","steps":["Hacer → haz; ver → no veas"],"answer":"Haz la tarea, pero no veas la tele."}]},{"say":"Let's talk about the future and what you would do. These tenses are easier than you think!","blocks":[{"t":"key","text":"The future tense adds endings to the whole infinitive: -é, -ás, -á, -emos, -éis, -án. Hablaré (I will speak), comerás, vivirá."},{"t":"p","text":"The conditional adds -ía endings to the infinitive: hablaría (I would speak), comerías, viviría."},{"t":"p","text":"Irregular stems (same for both tenses): tener → tendr-, salir → saldr-, poder → podr-, hacer → har-, decir → dir-, querer → querr-, venir → vendr-, saber → sabr-."},{"t":"ex","problem":"Say \"Tomorrow I will have a test, and I would like to study.\"","steps":["tener → tendré; gustar → me gustaría"],"answer":"Mañana tendré un examen y me gustaría estudiar."}]}]];
export default text;
